def get_public_statistics():
    """
    Computes live, verified public metrics for the homepage statistics cards directly from the database:
    1. total_complaints: COUNT(*) FROM complaints
    2. resolved_complaints: COUNT(*) FROM complaints WHERE status = 'Resolved'
    3. resolution_rate: (resolved / total) * 100 rounded to 1 decimal place (0.0% if total == 0)
    4. average_response_hours: Average time in hours from submission to first response/action (float or None)
    5. average_response_display: Human-readable string formatted e.g. '18h', '18h 32m', '45m', or '--' if none
    """
    conn = get_db_connection()
    total = conn.execute("SELECT COUNT(*) FROM complaints").fetchone()[0]
    resolved = conn.execute("SELECT COUNT(*) FROM complaints WHERE status = 'Resolved'").fetchone()[0]

    if total > 0:
        resolution_rate = round((resolved / total) * 100.0, 1)
        resolution_rate_display = f"{resolution_rate:.1f}%"
    else:
        resolution_rate = 0.0
        resolution_rate_display = "0.0%"

    complaint_rows = conn.execute("SELECT complaint_id, date, last_updated, first_responded_at FROM complaints").fetchall()
    history_rows = conn.execute("SELECT complaint_id, old_status, new_status, admin_name, admin_id, changed_at FROM complaint_status_history ORDER BY history_id ASC").fetchall()
    notes_rows = conn.execute("SELECT complaint_id, created_at FROM admin_notes ORDER BY note_id ASC").fetchall()
    conn.close()

    submission_map = {}
    response_map = {}

    for h in history_rows:
        cid = h["complaint_id"]
        if h["old_status"] is None or h["admin_name"] == "Student (Submission)":
            if cid not in submission_map:
                submission_map[cid] = h["changed_at"]
        else:
            if cid not in response_map:
                response_map[cid] = h["changed_at"]

    for n in notes_rows:
        cid = n["complaint_id"]
        if cid not in response_map:
            response_map[cid] = n["created_at"]

    durations = []
    for c in complaint_rows:
        cid = c["complaint_id"]
        sub_str = submission_map.get(cid) or c["date"] or c["last_updated"]
        resp_str = c["first_responded_at"] or response_map.get(cid)

        if sub_str and resp_str:
            sub_dt = parse_flexible_dt(sub_str)
            resp_dt = parse_flexible_dt(resp_str)
            if sub_dt and resp_dt and resp_dt >= sub_dt:
                sec = (resp_dt - sub_dt).total_seconds()
                durations.append(sec)

    if durations:
        avg_sec = sum(durations) / len(durations)
        avg_hours = avg_sec / 3600.0
        average_response_hours = round(avg_hours, 1)
        if avg_hours < 1:
            mins = max(1, round(avg_sec / 60))
            average_response_display = f"{mins}m"
        elif avg_hours < 24:
            hrs = int(avg_hours)
            mins = int((avg_sec % 3600) / 60)
            average_response_display = f"{hrs}h {mins}m" if mins > 0 else f"{hrs}h"
        else:
            days = int(avg_hours // 24)
            hrs = int(avg_hours % 24)
            average_response_display = f"{days}d {hrs}h" if hrs > 0 else f"{days}d"
    else:
        average_response_hours = None
        average_response_display = "--"

    return {
        "total_complaints": total,
        "resolved_complaints": resolved,
        "resolution_rate": resolution_rate,
        "resolution_rate_display": resolution_rate_display,
        "average_response_hours": average_response_hours,
        "average_response_display": average_response_display
    }
